import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    overageAllowedEnum,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { InvoiceLineItem, InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { OfferingType } from './OfferingType.js';
import { Offering } from './offeringPackage.entity.js';

jest.mock('../../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 0.91),
    },
}));

const businessID = 'fakeBusinessID';
const customerId = 'fakeCustomerID';

const dimensionOf = (overrides: Record<string, unknown>) => ({
    dimensionId: 'dim',
    dimensionName: 'Dimension',
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
    rounding: roundingEnum.round,
    usageIncrement: '1',
    consumptionUnit: {
        unit: countBasedUnits['count-based'],
        type: 'count',
    },
    ...overrides,
});

const gather = async ({
    dimensions,
    usage,
    settings,
}: {
    dimensions: any[];
    usage: number;
    settings?: ReadSettingsResponseData;
}): Promise<InvoiceLineItem[]> => {
    const offering: ReadOfferingResponseData = {
        offeringId: 'off',
        offeringName: 'Plan',
        offeringType: OfferingType.usageBased,
        currency: SupportedCurrencies.USD,
        billingCycle: ValidBillingCycles.monthly,
        dimensions,
    } as unknown as ReadOfferingResponseData;
    const startDate = new Date('2026-07-01T00:00:00Z');
    const endDate = new Date('2026-08-01T00:00:00Z');
    const offeringInstance = Offering.getInstance(
        offering,
        customerId,
        businessID,
        undefined,
        settings,
        undefined,
        undefined,
        undefined,
        dimensions.map(({ dimensionId }) => ({
            dimensionId,
            usage: [
                {
                    value: `${usage}`,
                    startTime: startDate.toISOString(),
                    endTime: endDate.toISOString(),
                },
            ],
        })) as any,
    );
    const lineItems = await Offering.getLineItemsForUsage({
        startDate,
        endDate,
        lineItems: new InvoiceLineItems(),
        negative: false,
        businessID,
        customerId,
        customerService: undefined,
        dimensions,
        offeringInstance,
    });
    return lineItems.getLineItems();
};

describe('Allowances, overage and free dimensions on metered invoice lines', () => {
    test('a dimension without an allowance is charged for all of its usage', async () => {
        const lineItems = await gather({
            dimensions: [dimensionOf({ consumptionPrice: '0.01' })],
            usage: 100,
        });
        expect(lineItems).toEqual([expect.objectContaining(new InvoiceLineItem('Dimension - Plan', 100, 0.01))]);
    });

    test('only the usage past an exhausted allowance is charged when overage is allowed', async () => {
        const lineItems = await gather({
            dimensions: [
                dimensionOf({
                    consumptionPrice: '10.00',
                    usageEntitlement: 10,
                    overageAllowed: overageAllowedEnum.true,
                }),
            ],
            usage: 12,
        });
        expect(lineItems).toEqual([expect.objectContaining(new InvoiceLineItem('Dimension - Plan', 2, 10))]);
    });

    test('an allowance that has not been exhausted charges nothing and earns no line', async () => {
        const lineItems = await gather({
            dimensions: [
                dimensionOf({
                    consumptionPrice: '0.02',
                    usageEntitlement: 100,
                    overageAllowed: overageAllowedEnum.true,
                }),
            ],
            usage: 80,
        });
        expect(lineItems).toEqual([]);
    });

    test('an unlimited allowance charges nothing and earns no line', async () => {
        const lineItems = await gather({
            dimensions: [
                dimensionOf({
                    consumptionPrice: '0.20',
                    usageEntitlement: 'inf',
                    overageAllowed: overageAllowedEnum.true,
                }),
            ],
            usage: 40,
        });
        expect(lineItems).toEqual([]);
    });

    test('a plan which forbids overage charges nothing beyond the allowance', async () => {
        const lineItems = await gather({
            dimensions: [
                dimensionOf({
                    consumptionPrice: '1.00',
                    usageEntitlement: 5,
                    overageAllowed: overageAllowedEnum.false,
                }),
            ],
            usage: 7,
        });
        expect(lineItems).toEqual([]);
    });

    test('an allowance without an overage rule charges nothing beyond the allowance', async () => {
        const lineItems = await gather({
            dimensions: [dimensionOf({ consumptionPrice: '0.10', usageEntitlement: 50 })],
            usage: 70,
        });
        expect(lineItems).toEqual([]);
    });

    test('a dimension the plan prices at zero earns a line when free dimensions are shown', async () => {
        const lineItems = await gather({
            dimensions: [dimensionOf({ consumptionPrice: '0.00' })],
            usage: 10,
            settings: { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData,
        });
        expect(lineItems).toEqual([expect.objectContaining(new InvoiceLineItem('Dimension - Plan', 10, 0))]);
    });

    test('a dimension the plan prices at zero is left off when free dimensions are hidden', async () => {
        const lineItems = await gather({
            dimensions: [dimensionOf({ consumptionPrice: '0.00' })],
            usage: 10,
            settings: { freeDimensionOnInvoice: FreeDimensionOnInvoice.hide } as ReadSettingsResponseData,
        });
        expect(lineItems).toEqual([]);
    });

    test('businesses without invoice settings still see free dimensions', async () => {
        const lineItems = await gather({
            dimensions: [dimensionOf({ consumptionPrice: '0' })],
            usage: 3,
        });
        expect(lineItems).toEqual([expect.objectContaining(new InvoiceLineItem('Dimension - Plan', 3, 0))]);
    });

    test('a charged dimension with no usage earns no line', async () => {
        const lineItems = await gather({
            dimensions: [dimensionOf({ consumptionPrice: '0.50' })],
            usage: 0,
        });
        expect(lineItems).toEqual([]);
    });
});
